def _find_choice_number(default: t.Any, choices: cabc.Sequence[t.Any]) -> int | None:
    # Return the 1-based menu number of the first choice matching the default.
    for number, choice in enumerate(choices, 1):
        if default == choice:
            return number

        if isinstance(default, str) and default == _choice_label(choice):
            return number

    return None


def _build_numbered_prompt(
    text: str,
    suffix: str,
    show_default: bool | str = False,
    default: t.Any | None = None,
    choices: cabc.Sequence[t.Any] = (),
) -> str:
    default_preview = ""

    if show_default:
        if isinstance(show_default, str):
            default_preview = f" [({show_default})]"
        elif default is not None:
            number = _find_choice_number(default, choices)

            if number is not None:
                default_preview = f" [{number}]"
            else:
                default_preview = f" [{_format_default(default)}]"

    return f"{text}{default_preview}{suffix}"


